// Consistent API Gateway HTTP API (payload format 2.0) response shaping,
// plus CORS headers on every response so the frontend can call these
// directly from the browser. CommonJS — see the note at the top of db.js
// for why.
function response(statusCode, body, extraHeaders = {}) {
  return {
    statusCode,
    headers: {
      "Content-Type": "application/json",
      "Access-Control-Allow-Origin": process.env.FRONTEND_URL || "*",
      "Access-Control-Allow-Headers": "Content-Type,Authorization",
      "Access-Control-Allow-Methods": "GET,POST,PUT,DELETE,OPTIONS",
      ...extraHeaders,
    },
    body: JSON.stringify(body),
  };
}

const ok = (body) => response(200, body);
const created = (body) => response(201, body);
const badRequest = (message) => response(400, { error: message || "Bad request" });
const unauthorized = (message) => response(401, { error: message || "Unauthorized" });
const forbidden = (message) => response(403, { error: message || "Forbidden" });
const notFound = (message) => response(404, { error: message || "Not found" });

function serverError(err) {
  console.error(err);
  return response(500, { error: "Internal server error" });
}

function getUserId(event) {
  return event.requestContext?.authorizer?.jwt?.claims?.sub || null;
}

/**
 * Identity on routes that allow anonymous access (auth = false).
 *
 * On those routes API Gateway never runs the JWT authorizer, so
 * requestContext.authorizer is absent even when the caller DID send a valid
 * token. getUserId therefore returns null for a perfectly good session, which
 * would make a signed-in follower look anonymous on a public route.
 *
 * This falls back to reading `sub` out of the Authorization header.
 *
 * SECURITY: the signature is NOT verified here, so this must only ever be used
 * to GRANT additional visibility to someone who would otherwise be treated as
 * an anonymous visitor — never to authorise a write, and never as the sole
 * gate on private data. Forging it gains an attacker exactly what any
 * signed-in user already has: nothing beyond a normal account's view. Anything
 * that must be trusted belongs on an auth = true route using getUserId.
 */
function getOptionalUserId(event) {
  const fromAuthorizer = getUserId(event);
  if (fromAuthorizer) return fromAuthorizer;
  try {
    const h = event.headers || {};
    const raw = h.authorization || h.Authorization;
    if (!raw) return null;
    const token = raw.startsWith("Bearer ") ? raw.slice(7) : raw;
    const payload = decodeJwtPayload(token);
    if (!payload) return null;
    // Reject anything already expired, so a stale token doesn't linger as
    // a usable identity.
    if (payload.exp && Date.now() / 1000 > payload.exp) return null;
    return payload.sub || null;
  } catch {
    return null;
  }
}

function parseBody(event) {
  if (!event.body) return {};
  try {
    return JSON.parse(event.isBase64Encoded ? Buffer.from(event.body, "base64").toString() : event.body);
  } catch {
    return {};
  }
}

// Decodes a JWT's payload without verifying the signature — used only for
// functions that need a claim (like sub) immediately after Cognito issues
// a token, before any request has gone through the JWT authorizer. Never
// use this as an authorization check; it's for reading data out of a token
// this same function just legitimately received from Cognito directly.
function decodeJwtPayload(token) {
  try {
    const payload = token.split(".")[1];
    return JSON.parse(Buffer.from(payload, "base64").toString("utf8"));
  } catch {
    return {};
  }
}

module.exports = { response, ok, created, badRequest, unauthorized, forbidden, notFound, serverError, getUserId, getOptionalUserId, parseBody, decodeJwtPayload };
